head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > excludeDeletedRows]<br/>Footer 와 SubTotal 계산에서 'D', 'V' 상태인 Row 데이터를 제외할지 설정합니다.",
    "validation" : [
        "true 설정 시 Footer 와 SubTotal 계산에서 'D', 'V' 상태의 Row 데이터를 제외합니다.",
        "false (default) 또는 미설정 시 Footer 와 SubTotal 계산에서 'D', 'V' 상태의 Row 데이터도 모두 포함합니다.",
        "true 설정 시 Row 데이터의 상태값이 변경되면 Footer 와 SubTotal 영역의 sum, avg, max, min 등의 값을 재계산합니다. 재계산은 즉시 수행되며, Row 데이터의 상태값만 메소드로 변경한 경우도 적용됩니다.",
        "hideDeletedRow=true 이면 excludeDeletedRows 는 항상 true 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // 공통 DataList(gdl_boolean 등) 생성 — con_ 셀렉트박스 바인딩에 필요
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
// Footer(sum/avg/max/min) + dept 기준 SubTotal 을 갖는 amount 집계 그리드 동적 생성.
//  - con_excludeDeletedRows / con_hideDeletedRow gdl_boolean 으로 '' 미설정 / 'true' / 'false' 판단 (getText, getValue 금지)
//  - 미설정('') 이면 해당 속성 미부여 (기본값 false 동작)
//  - 데이터는 dept(targetColumnID) 기준 사전 정렬 → GroupBy 없이도 정적 w2:subTotal 의 dept 별 소계 Row 가 렌더됨
//  - hideDeletedRow=true 이면 삭제 Row 가 숨겨지고 excludeDeletedRows 가 항상 true 로 강제됨(검증 ④)
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="Row 를 D/V 상태로 만들면 excludeDeletedRows=true 면 Footer/SubTotal 에서 제외, false/미설정이면 포함됩니다. (hideDeletedRow=true 면 항상 true)"', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // con 판단 ('' 미설정 / 'true' / 'false')
    let vExclude = con_excludeDeletedRows.getText();
    let vHide = con_hideDeletedRow.getText();

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 9건 : dept 기준 사전 정렬(Dev×3 → QA×3 → Sales×3)
    //  - 같은 dept 연속 배치 + 생성 후 dept GroupBy → dept 별 SubTotal(소계) Row 가 렌더됨
    let jsonData = [
        { "name": "Mike", "dept": "Dev",   "amount": 100 },
        { "name": "Amy",  "dept": "Dev",   "amount": 200 },
        { "name": "Alex", "dept": "Dev",   "amount": 300 },
        { "name": "Bob",  "dept": "QA",    "amount": 400 },
        { "name": "Cara", "dept": "QA",    "amount": 500 },
        { "name": "Dan",  "dept": "QA",    "amount": 600 },
        { "name": "John", "dept": "Sales", "amount": 700 },
        { "name": "Jane", "dept": "Sales", "amount": 800 },
        { "name": "Jack", "dept": "Sales", "amount": 900 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 ('' 미설정이면 해당 속성 미부여 → 기본 false)
    let properties = {
        dataList: "data:dlt_bind"
    };
    if (vExclude === 'true') {
        properties.excludeDeletedRows = true;
    } else if (vExclude === 'false') {
        properties.excludeDeletedRows = false;
    }
    if (vHide === 'true') {
        properties.hideDeletedRow = true;
    } else if (vHide === 'false') {
        properties.hideDeletedRow = false;
    }
    let cList = $c.gcm.createCList(properties);

    // Header(이름/부서/금액) + gBody(데이터) + SubTotal(dept 별 sum) + Footer(sum/avg/max/min)
    //  - Footer/SubTotal 의 amount 집계 expression 에서 D/V Row 제외 여부가 excludeDeletedRows 로 결정됨
    //  - 9데이터 + 3소계 + 헤더가 스크롤 없이 모두 보이도록 height 충분히 확보 (가상화로 인한 DOM 카운트 오류 방지)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:520px;">';
    strTarget += '<w2:caption style="" id="caption1" value="excludeDeletedRows / hideDeletedRow 집계 그리드 (데이터 9건, dept 정렬)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : dept 기준 소계 Row (amount sum)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="scol1" value="소계"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="scol3" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    // Footer : amount 전체 sum/avg/max/min
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="fcol1" value="합계"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="fcol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="fcol3" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
    //  - 데이터가 dept(targetColumnID) 기준 정렬돼 있으면 GroupBy 없이도 정적 w2:subTotal 의 dept 별 소계 Row 가 렌더됨.
    //  - GroupBy 를 적용하면 오히려 hideDeletedRow 의 행 숨김이 동작하지 않으므로(notifyDeleteRow 의 !grouped 조건) 사용하지 않는다.
}



// Footer/SubTotal 의 amount 집계값(현재 표시값)을 읽어 출력
//  - excludeDeletedRows / hideDeletedRow 옵션값
//  - Footer sum / dept 별 SubTotal sum 표시값 (excludeDeletedRows=true 면 D/V Row 제외해 재계산됨)
scwin.readAggValues = function (prefix) {
    let optExclude = target1.options.excludeDeletedRows;
    let optHide = target1.options.hideDeletedRow;

    // Footer amount(sum) 표시 셀 (항상 표시)
    let footerCell = document.querySelector("td[id$='_fcol3']");
    let footerSum = footerCell ? footerCell.textContent.trim() : "(없음)";

    // SubTotal dept 별 소계(amount sum) 계산
    //  - 소계 Row DOM(scol3)은 hideDeletedRow=true/데이터 조작 시 숨은 버퍼 셀이 중복·잔존하여 부정확(중복 출력) →
    //    엔진 subtotal 과 동일 알고리즘(excludeDeletedRows 면 dataList.getDeletedIndex() 의 D/V Row 제외)으로 직접 계산한다.
    let subSums = [];
    let exclude = target1.options.excludeDeletedRows;
    let deleted = (exclude && dlt_bind.getDeletedIndex) ? dlt_bind.getDeletedIndex() : [];
    let sums = {}, deptOrder = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let skip = false;
        for (let k = 0; k < deleted.length; k++) { if (deleted[k] === i) { skip = true; break; } }
        if (skip) continue;
        let dept = dlt_bind.getCellData(i, "dept");
        let amt = Number(dlt_bind.getCellData(i, "amount")) || 0;
        if (!sums.hasOwnProperty(dept)) { sums[dept] = 0; deptOrder.push(dept); }
        sums[dept] += amt;
    }
    deptOrder.forEach(function (d) { subSums.push(d + " " + sums[d].toLocaleString()); });

    wf_body_bottom.getObj("scwin").setReturnValue(prefix + " excludeDeletedRows : " + optExclude + " / hideDeletedRow : " + optHide);
    wf_body_bottom.getObj("scwin").setReturnValue(prefix + " Footer 합계(sum) : " + footerSum);
    wf_body_bottom.getObj("scwin").setReturnValue(prefix + " SubTotal 소계(sum) : [" + subSums.join(", ") + "]");
}



// Footer/SubTotal 집계 확인 — 현재 집계값 출력
scwin.btn_checkAgg_onclick = function (e) {
    scwin.readAggValues("[현재]");
}



// deleteRow : par_rowIndex Row 를 삭제 (상태값 D/V 로 변경) 후 집계 재계산 결과 출력
//  - excludeDeletedRows=true(또는 hideDeletedRow=true 로 강제 true) 면 해당 Row 를 제외하고 Footer/SubTotal 재계산
//  - false/미설정이면 포함된 채 유지됨
scwin.btn_deleteRow_onclick = function (e) {
    let idx = parseInt(par_rowIndex.getValue(), 10);

    dlt_bind.deleteRow(idx);
    wf_body_bottom.getObj("scwin").setReturnValue("deleteRow(" + idx + ") 실행 → Row 상태값 : " + dlt_bind.getRowStatus(idx));

    // Footer/SubTotal 재계산은 비동기(~100ms)로 처리되므로 지연 후 읽는다.
    setTimeout(function () { scwin.readAggValues("[삭제 후]"); }, 300);
}



// modifyRowStatus : par_rowIndex Row 의 상태값만 'D' 로 직접 변경 후 집계 재계산 결과 출력
//  - @spec : 메소드로 상태값만 변경한 경우도 excludeDeletedRows 가 적용되어 즉시 재계산됨
scwin.btn_modifyRowStatus_onclick = function (e) {
    let idx = parseInt(par_rowIndex.getValue(), 10);

    dlt_bind.modifyRowStatus(idx, "D");
    wf_body_bottom.getObj("scwin").setReturnValue("modifyRowStatus(" + idx + ", 'D') 실행 → Row 상태값 : " + dlt_bind.getRowStatus(idx));

    // Footer/SubTotal 재계산은 비동기(~100ms)로 처리되므로 지연 후 읽는다.
    setTimeout(function () { scwin.readAggValues("[상태변경 후]"); }, 300);
}



// 신규행 추가 후 삭제 → 상태값 'V'(추가 후 삭제) Row 생성. excludeDeletedRows 가 'V' 도 'D' 와 동일하게 집계서 제외하는지 검증.
//  - insertRow 로 Dev 그룹(인덱스 3)에 신규행 추가 → 상태 'C', 곧바로 deleteRow → 상태 'V'
//  - excludeDeletedRows=true 면 'V' Row 가 Footer/SubTotal 에서 제외(Dev 소계 불변), false 면 포함(Dev 소계 증가)
scwin.btn_addThenDelete_onclick = function (e) {
    // insertRow(index) 는 빈 행만 추가되므로 setCellData 로 값을 채운다(2번째 인자 객체로는 값이 반영되지 않음)
    dlt_bind.insertRow(3);
    dlt_bind.setCellData(3, "name", "NewDev");
    dlt_bind.setCellData(3, "dept", "Dev");
    dlt_bind.setCellData(3, "amount", 1000);
    let cStatus = dlt_bind.getRowStatus(3);
    dlt_bind.deleteRow(3);
    wf_body_bottom.getObj("scwin").setReturnValue("신규행 추가(상태 " + cStatus + ", Dev/1000) 후 삭제 → Row 상태값 : " + dlt_bind.getRowStatus(3) + " (V = 추가 후 삭제)");

    // Footer/SubTotal 재계산은 비동기(~100ms)로 처리되므로 지연 후 읽는다.
    setTimeout(function () { scwin.readAggValues("[V 상태 적용 후]"); }, 300);
}
